package com.aistock.prediction.verification;
import com.aistock.prediction.forecast.*;import com.aistock.prediction.marketuse.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@Tag("mysql") class VerificationMarketUseMysqlTest {
 @Test void actualVerificationUsesNewBoundRawAndNeverChangesOriginalPrediction(){var d=new VerificationMysqlTest();var id=d.forecast("SUCCEEDED",true);var before=d.f.jdbc.queryForObject("select snapshot_json from forecast_request where prediction_id=?",String.class,id.toString());var c=mock(MarketUseClient.class);var b=new MarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",List.of("22222222-2222-2222-2222-222222222222"));when(c.register(any())).thenReturn(b);when(c.complete(any(),any())).thenReturn(new MarketUseClient.Receipt(b.bundleId(),"RELEASED",b.versionIds()));var repo=new VerificationRepository(d.f.jdbc,VerificationMysqlTest.MAPPER,VerificationMysqlTest.NOW);var owner=new PredictionMarketUseOwner(d.f.jdbc,VerificationMysqlTest.MAPPER,new ForecastRepository(d.f.jdbc,VerificationMysqlTest.MAPPER,VerificationMysqlTest.NOW),repo,c,VerificationMysqlTest.NOW,true,true);var request=d.request(VerificationMysqlTest.TARGETS.get(0));VerificationMarketClient source=(r,p)->{assertEquals("PREDICTION_VERIFICATION",MarketUseContext.headers().get("X-Market-Use-Purpose"));return d.evidence(r.dueThrough(),UUID.randomUUID().toString(),"102");};var svc=new VerificationService(repo,source,new VerificationCalculator(),VerificationMysqlTest.MAPPER,VerificationMysqlTest.NOW,20,owner);var done=svc.verify(id,request);assertEquals("AVAILABLE",done.state());assertEquals("SUCCEEDED",owner.proof("PREDICTION_VERIFICATION",request.operationId(),"1").path("state").asText());assertEquals(done.versionId(),owner.proof("PREDICTION_VERIFICATION",request.operationId(),"1").path("resultIdentity").asText());assertEquals(before,d.f.jdbc.queryForObject("select snapshot_json from forecast_request where prediction_id=?",String.class,id.toString()));assertTrue(MarketUseContext.headers().isEmpty());}
 @Test void notDueHasNoRegistrationAndWrongGenerationCannotFinish(){var d=new VerificationMysqlTest();var id=d.forecast("SUCCEEDED",false);var repo=new VerificationRepository(d.f.jdbc,VerificationMysqlTest.MAPPER,VerificationMysqlTest.NOW);var c=mock(MarketUseClient.class);var owner=new PredictionMarketUseOwner(d.f.jdbc,VerificationMysqlTest.MAPPER,new ForecastRepository(d.f.jdbc,VerificationMysqlTest.MAPPER,VerificationMysqlTest.NOW),repo,c,VerificationMysqlTest.NOW,true,true);var source=mock(VerificationMarketClient.class);var svc=new VerificationService(repo,source,new VerificationCalculator(),VerificationMysqlTest.MAPPER,VerificationMysqlTest.NOW,20,owner);var r=d.request(VerificationMysqlTest.ORIGIN);assertEquals("SKIPPED_NOT_DUE",svc.verify(id,r).state());verifyNoInteractions(c,source);assertThrows(com.aistock.common.BusinessException.class,()->repo.finish(r.operationId(),2,"FAILED","LATE"));}

 @Test void mismatchedActualRawNeverPublishesVerification(){var d=new VerificationMysqlTest();var id=d.forecast("SUCCEEDED",false);var c=mock(MarketUseClient.class);when(c.register(any())).thenReturn(new MarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",List.of(UUID.randomUUID().toString())));var repo=new VerificationRepository(d.f.jdbc,VerificationMysqlTest.MAPPER,VerificationMysqlTest.NOW);var owner=new PredictionMarketUseOwner(d.f.jdbc,VerificationMysqlTest.MAPPER,new ForecastRepository(d.f.jdbc,VerificationMysqlTest.MAPPER,VerificationMysqlTest.NOW),repo,c,VerificationMysqlTest.NOW,true,true);var svc=new VerificationService(repo,(r,p)->d.evidence(r.dueThrough(),UUID.randomUUID().toString(),"102"),new VerificationCalculator(),VerificationMysqlTest.MAPPER,VerificationMysqlTest.NOW,20,owner);var r=d.request(VerificationMysqlTest.TARGETS.get(0));assertEquals("FAILED",svc.verify(id,r).state());assertEquals(0,d.f.jdbc.queryForObject("select count(*) from forecast_verification_version",Integer.class));assertEquals("FAILED",owner.proof("PREDICTION_VERIFICATION",r.operationId(),"1").path("state").asText());}
 @Test void verificationPermissionRefusalNeverCollectsActualData(){var d=new VerificationMysqlTest();var id=d.forecast("SUCCEEDED",false);var c=mock(MarketUseClient.class);doThrow(MarketUseClient.notReady()).when(c).requireReady();var repo=new VerificationRepository(d.f.jdbc,VerificationMysqlTest.MAPPER,VerificationMysqlTest.NOW);var owner=new PredictionMarketUseOwner(d.f.jdbc,VerificationMysqlTest.MAPPER,new ForecastRepository(d.f.jdbc,VerificationMysqlTest.MAPPER,VerificationMysqlTest.NOW),repo,c,VerificationMysqlTest.NOW,true,true);var source=mock(VerificationMarketClient.class);var svc=new VerificationService(repo,source,new VerificationCalculator(),VerificationMysqlTest.MAPPER,VerificationMysqlTest.NOW,20,owner);assertEquals("FAILED",svc.verify(id,d.request(VerificationMysqlTest.TARGETS.get(0))).state());verifyNoInteractions(source);verify(c,never()).register(any());}
 @Test void delayedGrantNeverStartsRealizationAfterLeaseOrBudgetExpires(){
  for(long leaseSeconds:new long[]{60,120}){
   var d=new VerificationMysqlTest();var id=d.forecast("SUCCEEDED",false);
   var now=VerificationMysqlTest.NOW.instant();var time=new java.util.concurrent.atomic.AtomicReference<>(now);
   Clock clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return time.get();}};
   var c=mock(MarketUseClient.class);
   var b=new MarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",List.of("22222222-2222-2222-2222-222222222222"));
   when(c.register(any())).thenAnswer(call->{time.set(now.plusSeconds(leaseSeconds==60?61:91));return b;});
   when(c.complete(any(),any())).thenReturn(new MarketUseClient.Receipt(b.bundleId(),"RELEASED",b.versionIds()));
   var repo=new VerificationRepository(d.f.jdbc,VerificationMysqlTest.MAPPER,clock);
   var owner=new PredictionMarketUseOwner(d.f.jdbc,VerificationMysqlTest.MAPPER,new ForecastRepository(d.f.jdbc,VerificationMysqlTest.MAPPER,clock),repo,c,clock,true,true);
   var source=mock(VerificationMarketClient.class);
   var svc=new VerificationService(repo,source,new VerificationCalculator(),VerificationMysqlTest.MAPPER,clock,20,owner);
   var r=new VerificationRequest(UUID.randomUUID(),VerificationMysqlTest.TARGETS.get(0),now.plusSeconds(leaseSeconds));
   var done=svc.verify(id,r);
   verifyNoInteractions(source);
   assertEquals("FAILED",done.state());
   assertEquals(leaseSeconds==60?"ATTEMPT_EXPIRED":"VERIFICATION_BUDGET_EXCEEDED",done.errorCode());
   verify(c).complete(any(),eq(b));
  }
 }

}
